h1 = stem(x, th, 'LineWidth', 2, 'Color', [0.7 0.7 0.7], 'MarkerSize', 5);
h2 = stem(x, p50, 'filled', 'LineWidth', 2.8, 'Color', [0.922 0.408 0.204], 'MarkerFaceColor', [0.922 0.408 0.204], 'MarkerSize', 6);
set(gca, 'XTick', 1:30, 'XTickLabel', {'B05', 'B03', 'B04', 'B01', 'N08', 'B02', 'S04', 'N01', 'N03', 'N04', 'N02', 'N10', 'N09', 'S02', 'S03', 'S01', 'N13', 'N11', 'A05', 'A02', 'N07', 'N12', 'A07', 'A03', 'A01', 'A04', 'A06', 'B06', 'N06', 'N05'});
